    assert Solution().levelOrderBottom(root) == [[4], [3], [2], [1]]


def test_right_skewed():
    root = TreeNode(1)
    root.right = TreeNode(2)
    root.right.right = TreeNode(3)
    assert Solution().levelOrderBottom(root) == [[3], [2], [1]]


def test_negative_values():
