                self.isScramble(s1[k:], s2[k:]) and self.isScramble(s1[:k], s2[:k])
            ) or (
                self.isScramble(s1[k:], s2[:-k]) and self.isScramble(s1[:k], s2[-k:])
            ): return True
        return False

